#!/usr/bin/env bash\nset -Eeuo pipefail\n\n: "${VPS_PASSWORD:?VPS_PASSWORD must be configured as a Replit Secret}"\n\nVPS_HOST="${VPS_HOST:-72.61.23.237}"\nVPS_PORT="${VPS_PORT:-22}"\nVPS_USER="${VPS_USER:-root}"\n\nif ! command -v sshpass >/dev/null 2>&1; then\n  echo "sshpass is required for VPS password authentication" >&2\n  exit 2\nfi\n\n# Pass the secret through the process environment only; never put it in arguments or logs.\nenv SSHPASS="$VPS_PASSWORD" sshpass -e ssh \\n  -o PreferredAuthentications=password \\n  -o PubkeyAuthentication=no \\n  -o StrictHostKeyChecking=accept-new \\n  -o LogLevel=ERROR \\n  -p "$VPS_PORT" \\n  "$VPS_USER@$VPS_HOST" \\n  'whoami; hostname'\n